INSERT OR REPLACE INTO clunk_asset_reviews (id, workspace_id, asset_id, visual_runtime, player_facing, human_decision, note, evidence_json, reviewer_user_id) VALUES ('review-dock-dock-plank-straight', 'ws-artemis-store', 'asset-dock-dock-plank-straight', 'PASS', 'NOT_EVALUATED', 'PASS', '부두·낚시터 키트 — 형상 감사·6각도 대조표·로컬 MCP·원격 MCP 네 가지로 검사한 파일', '{"source":"kit-fishing-dock","builder":"examples/generated/kits/fishing-dock/build.mjs","geometryAudit":"scripts/asset-geometry-audit.mjs","visualSweep":"outputs/visual-sweep/dock-plank-straight.png","localMcp":"integrations/mcp/server.ts clunk_asset_inspect","remoteMcp":"https://clunk.games/api/mcp clunk_asset_validate","qa":"tmp/kits/fishing-dock/qa/dock-plank-straight.json"}', 'usr-artemis-store');
INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-dock-dock-plank-straight', 'ws-artemis-store', 'asset-dock-dock-plank-straight', 'dock-plank-straight', '곧은 부두 판자 모듈', '부두를 곧게 이어 가는 갑판 한 칸입니다. 평면 2.000 × 2.000 m, 걷는 면 높이 0.860 m. 폭 160 mm · 두께 50 mm 판자를 182 mm 간격으로 깔아 물이 빠지는 틈이 형상으로 남아 있고, 그 아래에 받침보 네 줄이 지나갑니다. 말뚝 두 개가 갑판을 지나 판자 위로 335 mm 올라오며, 말뚝이 지나는 자리는 판자를 잘라 내고 받침보도 끊어 두었습니다. 모서리·끝 모듈과 치수가 같아 2 m 격자 위에 나란히 놓으면 높이도 판자 간격도 이어집니다. 삼각형 828개, 재질 4개.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);

