INSERT OR REPLACE INTO clunk_asset_reviews (id, workspace_id, asset_id, visual_runtime, player_facing, human_decision, note, evidence_json, reviewer_user_id) VALUES ('review-dock-dock-plank-corner', 'ws-artemis-store', 'asset-dock-dock-plank-corner', 'PASS', 'NOT_EVALUATED', 'PASS', '부두·낚시터 키트 — 형상 감사·6각도 대조표·로컬 MCP·원격 MCP 네 가지로 검사한 파일', '{"source":"kit-fishing-dock","builder":"examples/generated/kits/fishing-dock/build.mjs","geometryAudit":"scripts/asset-geometry-audit.mjs","visualSweep":"outputs/visual-sweep/dock-plank-corner.png","localMcp":"integrations/mcp/server.ts clunk_asset_inspect","remoteMcp":"https://clunk.games/api/mcp clunk_asset_validate","qa":"tmp/kits/fishing-dock/qa/dock-plank-corner.json"}', 'usr-artemis-store');
INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-dock-dock-plank-corner', 'ws-artemis-store', 'asset-dock-dock-plank-corner', 'dock-plank-corner', '꺾이는 부두 판자 모듈', '부두가 방향을 바꾸는 갑판 칸입니다. 두 변이 열려 있고 그 사이를 45도 이음판이 가르며, 이음판을 경계로 한쪽 판자는 세로로 다른 쪽은 가로로 깔립니다 — 목조 잔교가 실제로 모서리를 도는 방식입니다. 평면 2.000 × 2.000 m, 걷는 면 0.860 m 로 곧은 모듈과 같고, 이음판 아래에는 대각선 받침보가 따로 들어 있습니다. 말뚝 네 개가 닫힌 두 변을 받치고, 말뚝 자리마다 판자를 잘라 냈습니다. 삼각형 1,488개, 재질 4개.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);

