INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-dock-dock-plank-end', 'ws-artemis-store', 'asset-dock-dock-plank-end', 'dock-plank-end', '부두 끝 모듈', '부두의 마지막 갑판 칸입니다. 한 변만 열려 있고 나머지 세 변은 옆판으로 막았으며, 끝에는 판자 위로 90 mm 올라오는 턱목을 놓아 내려놓은 상자가 물 쪽으로 미끄러지지 않습니다. 평면 2.000 × 2.000 m, 걷는 면 0.860 m, 말뚝 네 개. 곧은 모듈에 그대로 이어 붙습니다. 삼각형 1,236개, 재질 4개.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);

