INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-dock-dock-piling', 'ws-artemis-store', 'asset-dock-dock-piling', 'dock-piling', '따로 서 있는 계선 말뚝', '갑판에서 떨어져 혼자 박혀 있는 각목 말뚝입니다. 200 mm 각재에 전체 높이 1.795 m, 머리를 사방으로 깎아 놓았고 쇠테 네 조각과 밧줄 두 감기가 걸려 있습니다. 밧줄은 각재의 네 면에 붙는 네 토막으로 되어 있어 둥근 테가 말뚝 둘레에 떠 있는 모양이 되지 않습니다. 갑판 모듈에 들어 있는 말뚝(위 끝 1.195 m)보다 600 mm 높아 나란히 세워도 같은 부품으로 보이지 않습니다. 삼각형 216개, 재질 3개.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);

