INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-dock-dock-bollard', 'ws-artemis-store', 'asset-dock-dock-bollard', 'dock-bollard', '주철 계선주', '밧줄을 걸어 배를 매는 계선주입니다. 높이 0.470 m, 버섯머리 지름 0.300 m, 바닥 플랜지 0.320 m 에 볼트 네 개가 솟아 있습니다. 밧줄 두 감기가 목에 걸려 있고 한 가닥이 갑판 위로 흘러나갑니다. 플랜지가 그대로 y = 0 에 앉으므로 파일의 바닥면이 곧 갑판면입니다. 삼각형 550개, 재질 2개.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);

