INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-dock-dock-lantern-post', 'ws-artemis-store', 'asset-dock-dock-lantern-post', 'dock-lantern-post', '등불이 걸린 기둥', '갑판에 세우는 각목 등 기둥입니다. 전체 높이 2.610 m, 팔은 2.30 m 지점에서 0.62 m 뻗어 나가고 그 끝 갈고리에 네 면 유리 등불이 걸립니다. 기둥은 갑판을 뚫지 않고 십자로 깐 받침목과 무릎 버팀목 네 개로 서 있습니다. 등불은 `lantern_pivot` 노드에 매달려 있고, 파일 안에 3.2초짜리 `sway` 동작이 들어 있어 그 노드를 회전만으로 흔듭니다 — 크기 채널은 쓰지 않습니다. 삼각형 720개, 재질 5개.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);

