INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-dock-dock-rod-rack', 'ws-artemis-store', 'asset-dock-dock-rod-rack', 'dock-rod-rack', '낚싯대 세 대가 얹힌 거치대', '낚싯대가 함께 들어 있는 나무 거치대입니다. 가대 두 짝이 1.24 m 떨어져 서고, 가대마다 얹힌 안장 턱이 낚싯대가 옆으로 구르지 않게 잡습니다. 낚싯대는 길이 2.05 m 로 두 가대에 함께 얹히고 끝은 지름 12 mm 까지 가늘어지며, 바깥 두 대에는 릴이 달려 있습니다. 아래 선반에는 도구함이 놓입니다. 전체 2.050 × 1.020 × 1.120 m, 삼각형 1,340개, 재질 6개.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);

