INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-dock-dock-buoy-red', 'ws-artemis-store', 'asset-dock-dock-buoy-red', 'dock-buoy-red', '붉은 원통 계선 부표', '배를 매어 두는 뭉툭한 계선 부표입니다. 지름 0.526 m, 높이 0.735 m. 흰 띠는 겉에 칠한 것이 아니라 몸통을 세 토막으로 나눠 따로 두른 형상이라 두 면이 같은 자리에서 겹치지 않습니다. 위에는 들어 올리는 고리, 아래에는 사슬 섀클이 달려 있습니다. 물에 뜨는 물건이지만 파일에서는 바닥 y = 0 에 앉혀 두었습니다 — 0.235 m 만큼 내려놓으면 흰 띠가 수면에 옵니다. 삼각형 542개, 재질 4개.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);

