INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-dock-dock-buoy-white', 'ws-artemis-store', 'asset-dock-dock-buoy-white', 'dock-buoy-white', '흰 장대 부표', '파도 위로 보이라고 만든 가늘고 긴 부표입니다. 부력체 지름 0.366 m, 장대 꼭대기까지 높이 1.353 m, 위에는 십자 톱마크가 달려 있습니다. 붉은 원통 부표와 색만 바꾼 것이 아니라 형태가 다른 부품입니다. 흘수 0.200 m — 그만큼 내려놓으면 파란 띠가 수면에 옵니다. 삼각형 494개, 재질 3개.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);

