INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-dock-dock-rowboat', 'ws-artemis-store', 'asset-dock-dock-rowboat', 'dock-rowboat', '노 두 자루가 실린 나룻배', '부두에 매어 두는 두 사람용 나룻배입니다. 길이 3.100 m, 폭 1.366 m, 흘수 0.190 m. 선체는 바깥 껍질과 32 mm 안쪽의 속 껍질을 뱃전·고물·이물 면으로 이어 붙인 껍데기라서 갑판 위에서 내려다보면 배 안이 보입니다 — 가로대 세 개, 바닥널 네 장, 뱃전에 앉은 노받이 두 개, 이물의 밧줄 사리가 그 안에 있습니다. 노 두 자루는 배 안에 눕혀 실었습니다. 파란 뱃전 띠는 칠이 아니라 맨 윗 널을 따로 나눈 것입니다. 파일 안에 4초짜리 `bob` 동작이 들어 있어 `boat_pivot` 노드를 회전과 이동만으로 흔듭니다. 삼각형 1,160개, 재질 6개.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);

