INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-dock-dock-lighthouse', 'ws-artemis-store', 'asset-dock-dock-lighthouse', 'dock-lighthouse', '부두 끝의 작은 등대', '잔교 끝에 세우는 작은 등대입니다. 전체 높이 4.366 m, 난간이 두른 발코니가 3.24 m, 가장 넓은 곳이 발코니의 1.440 m 라서 2 m 갑판 모듈 한 칸 위에 그대로 올라갑니다. 붉은·흰 띠는 겉에 칠한 것이 아니라 탑을 네 토막으로 나눠 두른 형상이고, 문과 창 세 짝도 벽에 그린 것이 아니라 벽 앞에 붙은 틀입니다. 등롱 안 회전등은 `beacon_pivot` 노드에 달려 있고, 6초짜리 `beacon-spin` 동작이 한 바퀴를 90도씩 네 번에 나눠 돌립니다. 삼각형 1,364개, 재질 7개.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);

