INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-dock-kit-fishing-dock', 'ws-artemis-store', 'asset-dock-kit-fishing-dock', 'kit-fishing-dock', '부두·낚시터 키트 (부품 15개)', '호숫가 부두 한 벌을 한 파일에 담았습니다. 갑판 모듈 3종, 계선 말뚝, 계선주, 등불 기둥, 낚싯대 거치대, 생선 상자 2종, 그물 더미, 밧줄 사리, 부표 2종, 나룻배, 작은 등대 — 모두 15개가 바닥 격자 위에 상자 사이 0.6 m 를 두고 놓여 있고, 부품마다 자기 이름을 단 노드 아래에 들어 있습니다. 색은 12색 한 벌뿐이고 그중 8색은 코지 팜 세트가 쓰는 값 그대로라 농장 물건과 같은 세계에 놓입니다. 삼각형 13,926개, 재질 12개, 동작 3개(나룻배 흔들림·등불 흔들림·등대 등 회전). 이 파일의 크기는 늘어놓은 간격이지 부품의 크기가 아니므로 사양에 적지 않았습니다 — 부품마다 따로 받을 수 있는 파일이 함께 있고, 크기는 거기에 적혀 있습니다.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
